% Preliminaries

\section{Preliminaries}
\label{sec:preliminaries}
We consider the following class of programs whose states are real-valued vectors.

\begin{definition}[Linear lasso program]\label{def:linear-lassos}
A \emph{(conjunctive) linear lasso program} $P = (\stemt, \loopt)$ consists of two binary relations $\stemt$ and $\loopt$,
that are each defined by a formula whose free variables are $\vec{x}$ and $\vec{x}'$ and that have the form
$A\abovebelow{\vec{x}}{\vec{x}'} \leq \vec{b}$
for some matrix $A \in \mathbb{R}^{n \times m}$
and some vector $\vec{b} \in \mathbb{R}^{m}$.
We call a linear lasso program \emph{linear loop program} if the formula that defines the relation $\stemt$ is equivalent to $true$.
\end{definition}

\begin{definition}[Infinite execution]\label{def:nontermination}
An infinite sequence of states $(\vec{x}_t)_{t \geq 0}$ is an \emph{infinite execution} of the linear lasso program $P = (\stemt,\loopt)$ iff
$(\vec{x}_0, \vec{x}_1) \in \stemt$ and $(\vec{x}_t, \vec{x}_{t+1}) \in \loopt$ for all $t \geq 1$.
\end{definition}


